using UnityEngine;
using UnityEngine.UIElements;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var hud = GameObject.Find("HudRoot");
        var doc = hud.GetComponent<UIDocument>();
        var root = doc.rootVisualElement;
        var bindings = hud.GetComponent<Homesteader.UI.HudBindings>();
if (bindings != null) bindings.SendMessage("Update", SendMessageOptions.DontRequireReceiver);
string[] names = new string[] { "VitalWellnessFill", "VitalStaminaFill", "VitalThirstFill", "VitalHungerFill" };
        foreach (var n in names)
        {
            var e = root.Q<VisualElement>(n);
            if (e == null) { result.Log(n + " NULL"); continue; }
            result.Log(n
             + " resW="
             + e.resolvedStyle.width
             + " layoutW="
             + e.layout.width
             + " flexGrow="
             + e.style.flexGrow.value
             + " sWv="
             + e.style.width.value
            );
        }
    }
}
